<script setup lang="ts">
import { computed, onUnmounted, ref, watch } from 'vue'
import {httpClient} from '@/shared/http/client'
import {validateSceneFiles} from './intake'
const props=defineProps<{modelValue:File[];locked:boolean}>(),emit=defineEmits<{'update:modelValue':[files:File[]]}>()
const error=ref(''),uploaded=ref(0),progress=ref('')
const jobs=new Map<File,{key:string;done:boolean}>(),urls=new Map<File,string>()
const previews=computed(()=>props.modelValue.map(file=>{if(!urls.has(file))urls.set(file,URL.createObjectURL(file));return {file,url:urls.get(file)!}}))
watch(()=>props.modelValue,files=>{for(const [file,url] of urls)if(!files.includes(file)){URL.revokeObjectURL(url);urls.delete(file)}})
function choose(event:Event){const input=event.target as HTMLInputElement;try{const files=[...props.modelValue,...Array.from(input.files??[])];validateSceneFiles(files);emit('update:modelValue',files);error.value=''}catch(e){error.value=e instanceof Error?e.message:'照片选择失败'}finally{input.value=''}}
async function upload(caseId:string){validateSceneFiles(props.modelValue);uploaded.value=0;try{for(const file of props.modelValue){let job=jobs.get(file);if(!job){job={key:crypto.randomUUID(),done:false};jobs.set(file,job)}if(!job.done){progress.value=`正在保存 ${uploaded.value+1}/${props.modelValue.length}`;const body=new FormData();body.append('file',file,file.name);body.append('category','SCENE_PHOTO');await httpClient.post(`/materials/cases/${caseId}`,body,{headers:{'Content-Type':undefined,'Idempotency-Key':job.key}});job.done=true}uploaded.value++}progress.value=uploaded.value?`已保存${uploaded.value}张`:''}catch(e){progress.value=`已保存${uploaded.value}张，剩余照片可重试`;throw e}}
onUnmounted(()=>{for(const url of urls.values())URL.revokeObjectURL(url)})
defineExpose({upload})
</script>
<template><section class="scene-photos"><header><div><h2>现场物损照片</h2><p>JPG / PNG · 每张10 MiB以内 · 最多20张</p></div><FileDropZone :files="modelValue" hint="JPG/JPEG/PNG；支持批量，每张≤10 MiB，合计≤20张。选择后在下方预览或移除，建单时上传。" :max-bytes="10485760" :error="error" :feedback="progress" :disabled="locked" :busy="progress.startsWith('正在保存')"><label class="choose-photo">添加照片<input type="file" multiple accept=".jpg,.jpeg,.png" :disabled="locked" @change="choose"/></label></FileDropZone></header><div v-if="previews.length" class="photo-grid"><figure v-for="(item,index) in previews" :key="item.url"><img :src="item.url" :alt="'物损照片 '+(index+1)"/><figcaption><span>{{ item.file.name }} · {{ item.file.size }} B · {{ jobs.get(item.file)?.done?'上传成功':progress.startsWith('正在保存')?'上传／处理中':'待上传' }}</span><button :disabled="locked||jobs.get(item.file)?.done" @click="emit('update:modelValue',modelValue.filter((_,i)=>i!==index))">移除</button></figcaption></figure></div><p v-else class="empty">尚未添加照片，正式建单至少需要1张。</p><p v-if="error" role="alert">{{ error }}</p><p v-if="progress" role="status">{{ progress }}</p></section></template>
<style scoped>.scene-photos{border-top:1px solid #dce5e4;padding:20px 0}.scene-photos header{display:flex;justify-content:space-between;align-items:center;gap:16px}.scene-photos h2{font-size:17px;margin:0}.scene-photos p{font-size:12px;color:#596a65}.choose-photo{position:relative;padding:9px 12px;border:1px solid #bdceca;border-radius:8px;cursor:pointer;font-size:13px}.choose-photo input{position:absolute;inset:0;opacity:0;width:100%;cursor:pointer}.photo-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(125px,1fr));gap:12px}.photo-grid figure{margin:0;min-width:0}.photo-grid img{width:100%;aspect-ratio:4/3;object-fit:cover;border-radius:8px}.photo-grid figcaption{display:flex;gap:4px;font-size:11px}.photo-grid span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1}.photo-grid button{border:0;background:none;color:#596a65;cursor:pointer}.empty{padding:16px 0}</style>
